
import Cocoa
import WebKit

let htmlContent = #"""
<!DOCTYPE html>
<html lang="tr">
<head>
<meta charset="UTF-8">
<style>
  :root { 
    --text-main: #ffffff; --text-dim: rgba(255,255,255,0.55); 
    --bg-card: rgba(255,255,255,0.08); --bg-card-hover: rgba(255,255,255,0.16); 
    --green: #2ecc71; --orange: #f39c12; --red: #e74c3c; --blue: #3498db;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; font-family: -apple-system, BlinkMacSystemFont, "SF Pro Display", sans-serif; user-select: none; }
  body { background: transparent; color: var(--text-main); width: 400px; height: 720px; overflow: hidden; }
  #app-wrapper { width: 400px; height: 720px; display: flex; flex-direction: column; position: relative; }

  .tab-container { flex-grow: 1; height: calc(100% - 70px); position: relative; }
  .tab-content { position: absolute; top: 0; left: 0; width: 100%; height: 100%; padding: 20px 16px; overflow-y: auto; display: none; flex-direction: column; }
  .tab-content.active { display: flex; }
  #tab-map, #tab-direct { padding: 10px; }
  ::-webkit-scrollbar { width: 0px; }

  .top-bar { display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px; }
  .status-label { display: flex; align-items: center; gap: 8px; font-size: 14px; font-weight: 600; color: #eee; }
  .status-label svg { width: 18px; height: 18px; stroke: currentColor; fill: none; }
  .power-btn { width: 42px; height: 42px; border-radius: 50%; border: 1px solid rgba(255,255,255,0.2); display: flex; justify-content: center; align-items: center; cursor: pointer; transition: 0.2s; background: rgba(0,0,0,0.25);}
  .power-btn.on { background: #fff; border-color: #fff; box-shadow: 0 0 16px rgba(255,255,255,0.35); }
  .power-btn svg { width: 20px; height: 20px; stroke: var(--text-main); fill: none; stroke-width: 2; transition: 0.2s;}
  .power-btn.on svg { stroke: #000; }

  /* Donanım Sensör Durum Rozetleri */
  .hw-badge-row { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; margin-bottom: 12px; }
  .hw-badge { background: rgba(0,0,0,0.3); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 7px 4px; display: flex; flex-direction: column; align-items: center; gap: 4px; transition: 0.2s; }
  .hw-badge svg { width: 16px; height: 16px; stroke: var(--text-dim); fill: none; }
  .hw-badge span { font-size: 10px; color: var(--text-dim); text-align: center; }
  .hw-badge.active { border-color: var(--blue); background: rgba(52, 152, 219, 0.15); }
  .hw-badge.active svg { stroke: var(--blue); }
  .hw-badge.active span { color: #fff; font-weight: 600; }
  .hw-badge.warn { border-color: var(--orange); background: rgba(243, 156, 18, 0.15); }
  .hw-badge.warn svg { stroke: var(--orange); }
  .hw-badge.warn span { color: var(--orange); font-weight: 600; }
  .hw-badge.err { border-color: var(--red); background: rgba(231, 76, 60, 0.15); }
  .hw-badge.err svg { stroke: var(--red); }
  .hw-badge.err span { color: var(--red); font-weight: 600; }

  /* Görsel / GIF Alanı */
  .visual-area { height: 135px; display: flex; justify-content: center; align-items: center; margin-bottom: 12px; }
  .vac-frame-box { 
    width: 200px; height: 130px; 
    border-radius: 14px; overflow: hidden; 
    display: flex; justify-content: center; align-items: center;
    box-shadow: 0 8px 24px rgba(0,0,0,0.5);
    border: 1px solid rgba(255,255,255,0.1);
    background: #000;
  }
  .vac-img-render { width: 100%; height: 100%; object-fit: cover; }

  .main-val-row { display: flex; justify-content: space-between; align-items: flex-end; margin-bottom: 18px;}
  .main-val { font-size: 58px; font-weight: 300; line-height: 0.8; letter-spacing: -2px;}
  .main-val span { font-size: 20px; color: var(--text-dim); font-weight: 400; letter-spacing: 0;}
  .conn-status-text { font-size: 12px; color: var(--green); font-weight: 600; text-transform: uppercase; margin-bottom: 6px; }

  .slider-row { display: flex; align-items: center; gap: 12px; margin-bottom: 4px;}
  .s-btn { color: var(--text-dim); cursor: pointer; font-size: 22px; width: 26px; text-align: center; font-weight: 400;}
  .s-track { flex-grow: 1; height: 28px; background: rgba(0,0,0,0.4); border-radius: 14px; position: relative; overflow: hidden; display: flex; align-items: center; padding: 0 4px;}
  .s-fill { height: 20px; width: 0%; background: rgba(255,255,255,0.9); border-radius: 10px; transition: 0.3s cubic-bezier(0.2,0.8,0.2,1); position:relative;}
  .s-labels { display: flex; justify-content: center; font-size: 12px; font-weight: 500; color: var(--text-main); margin-bottom: 16px;}

  .cards-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-bottom: 8px;}
  .cards-grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; }
  .card { background: var(--bg-card); border-radius: 12px; padding: 12px 6px; display: flex; flex-direction: column; align-items: center; gap: 6px; cursor: pointer; transition: 0.2s;}
  .card:active { transform: scale(0.95); background: var(--bg-card-hover); }
  .card svg { width: 18px; height: 18px; stroke: var(--text-dim); fill: none; stroke-width: 1.5; }
  .card .c-title { font-size: 10px; color: var(--text-dim); text-align: center; }
  .card .c-val { font-size: 12px; font-weight: 600; text-align: center; color: var(--text-main);}

  .telemetry-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-bottom: 12px; }
  .telem-box { background: rgba(0,0,0,0.3); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 9px 11px; }
  .telem-title { font-size: 10px; color: var(--text-dim); text-transform: uppercase; margin-bottom: 3px; font-weight: 600; }
  .telem-val { font-size: 12px; font-weight: 600; color: #fff; }

  /* Harita & Frame Görünümü */
  .frame-box { flex-grow: 1; width: 100%; border-radius: 14px; overflow: hidden; background: #0c1017; border: 1px solid rgba(255,255,255,0.12); margin-bottom: 10px; position: relative; display: flex; justify-content: center; align-items: center; }
  .frame-inner { width: 100%; height: 100%; border: none; }
  #mapCanvas { width: 100%; height: 100%; display: block; }
  .map-toolbar { display: flex; gap: 6px; align-items: center; }

  .select-map { background: rgba(0,0,0,0.6); border: 1px solid rgba(255,255,255,0.15); color: #fff; padding: 8px; border-radius: 8px; font-size: 12px; outline: none; flex-grow: 1; }
  .btn-action { padding: 10px 14px; background: #fff; color: #000; border: none; border-radius: 9px; font-weight: 600; font-size: 12px; cursor: pointer; white-space: nowrap; }

  .section-title { font-size: 11px; color: var(--text-dim); text-transform: uppercase; letter-spacing: 1px; margin-bottom: 10px; margin-top: 12px; font-weight: 600;}
  .input-group { margin-bottom: 10px;}
  .input-group label { display: block; font-size: 11px; color: #aaa; margin-bottom: 4px;}
  .input-group input { width: 100%; padding: 10px; background: rgba(0,0,0,0.6); border: 1px solid rgba(255,255,255,0.15); color: #fff; border-radius: 8px; font-size: 12px; outline:none;}

  .bottom-nav { height: 70px; display: flex; justify-content: space-around; align-items: center; background: rgba(22,22,22,0.92); backdrop-filter: blur(25px); border-top: 1px solid rgba(255,255,255,0.08); z-index: 50;}
  .nav-item { display: flex; flex-direction: column; align-items: center; gap: 4px; color: var(--text-dim); cursor: pointer; transition: 0.2s; width: 65px;}
  .nav-item svg { width: 20px; height: 20px; stroke: currentColor; fill: none; stroke-width: 1.5; }
  .nav-item span { font-size: 10px; font-weight: 500; }
  .nav-item.active { color: var(--text-main); }
</style>
</head>
<body>

<div id="app-wrapper">
  
  <div class="tab-container">
    
    <!-- TAB 1: KONTROL -->
    <div id="tab-home" class="tab-content active">
      <div class="top-bar">
        <div class="status-label"><svg viewBox="0 0 24 24"><path d="M16.7 8V6a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h10.7a2 2 0 0 0 2-2v-2"></path><rect x="19" y="10" width="3" height="4" rx="1"></rect></svg>Shark RV2000</div>
        <div class="power-btn" id="pwrBtn" onclick="togglePower()"><svg viewBox="0 0 24 24"><path d="M18.36 6.64a9 9 0 1 1-12.73 0"></path><line x1="12" y1="2" x2="12" y2="12"></line></svg></div>
      </div>

      <!-- Canlı Donanım Rozetleri -->
      <div class="hw-badge-row">
