      <!-- Komutlar -->
      <div class="cards-grid">
        <div class="card" onclick="sendCmd('/set/clean_start_or_continue?cleaning_parameter_set=' + suctionIndex, 'Başlatılıyor')">
          <svg viewBox="0 0 24 24"><polygon points="5 3 19 12 5 21 5 3"></polygon></svg>
          <div class="c-title">Temizle</div><div class="c-val">Clean</div>
